const key = ($input.first().json.jooble_key || "").replace(/[^a-zA-Z0-9-]/g, "");
const KEYWORDS = [
  "Industrial Engineer", "Safety Officer", "HSE", "Process Engineer",
  "Quality Engineer", "Supply Chain", "Internal Auditor", "Risk Management",
  "Industrial Engineering Intern", "Tamheer", "Trainee", "Coop"
];
return KEYWORDS.map((keyword) => ({ json: { jooble_key: key, keyword } }));

const TOKENS = [
  "tamara",
];
return TOKENS.map((token) => ({ json: { token } }));

const TITLE_INCLUDE = [
  "industrial engineer", "safety officer", "hse", "process engineer",
  "quality", "supply chain", "internal auditor", "risk management"
];
const INTERN_TERMS = ["intern", "internship", "coop", "co-op", "co op", "trainee", "tamheer"];
const SENIORITY_EXCLUDE = ["senior", "manager", "director", "vp", "lead", "head"];
const ACCEPT_LOCATIONS = ["saudi arabia", "ksa", "remote"];
const JEDDAH_SIGNALS = ["jeddah", "western region", "makkah province", "makkah region"];
const existing = new Set();
const existingTC = new Set();
const tcKey = (t, c) => String(t || "").toLowerCase().trim() + "|" + String(c || "").toLowerCase().trim();
for (const it of $("Get Existing Jobs").all()) {
  const row = it.json || {};
  const u = row.job_url ? String(row.job_url).trim() : "";
  if (u) { existing.add(u); }
  if (row.job_title || row.company) { existingTC.add(tcKey(row.job_title, row.company)); }
}
const hasWord = (text, term) => {
  const t = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp("(^|[^a-z0-9])" + t + "([^a-z0-9]|$)", "i").test(text);
};
const decodeEntities = (s) => String(s || "")
  .replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&#x27;/gi, "'")
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&");
const stripHtml = (s) => String(s || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
const seen = new Set();
const out = [];
const tryAccept = ({ title, company, desc, locName, url, email }) => {
  const titleLc = String(title || "").toLowerCase();
  const hay = (String(title || "") + " " + String(desc || "")).toLowerCase();
  const loc = String(locName || "").toLowerCase();
  const isIntern = INTERN_TERMS.some((k) => titleLc.includes(k));
  const titleHit = TITLE_INCLUDE.some((k) => titleLc.includes(k)) || isIntern;
  if (!titleHit) { return; }
  if (!isIntern && SENIORITY_EXCLUDE.some((k) => hasWord(titleLc, k))) { return; }
  const locationHit = ACCEPT_LOCATIONS.some((l) => loc.includes(l))
    || JEDDAH_SIGNALS.some((s) => hay.includes(s));
  if (!locationHit) { return; }
  const dedupeKey = titleLc + "|" + String(company || "").toLowerCase().trim();
  if (seen.has(dedupeKey)) { return; }
  seen.add(dedupeKey);
  if (url && existing.has(url)) { return; }
  if (existingTC.has(dedupeKey)) { return; }
  const jeddahSignal = JEDDAH_SIGNALS.some((s) => hay.includes(s)) || loc.includes("jeddah");
  out.push({ json: {
    job_title: title,
    company: company || "Unknown",
    job_description: desc,
    location: jeddahSignal ? (locName + " (Jeddah signal)") : locName,
    job_url: url,
    contact_email: email || "",
    status: "new",
    applied: false,
  }});
};
for (const respItem of $("Fetch Jooble Jobs").all()) {
  const resp = respItem.json || {};
  const jobs = Array.isArray(resp.jobs) ? resp.jobs : [];
  for (const j of jobs) {
    tryAccept({
      title: j.title || "",
      company: j.company || j.source || "Unknown",
      desc: stripHtml(j.snippet),
      locName: j.location || "",
      url: j.link || "",
    });
  }
}
for (const respItem of $("Fetch Greenhouse Jobs").all()) {
  const resp = respItem.json || {};
  const jobs = Array.isArray(resp.jobs) ? resp.jobs : [];
  for (const j of jobs) {
    const loc = (j.location && j.location.name) ? j.location.name : "";
    tryAccept({
      title: j.title || "",
      company: j.company_name || "Tamara",
      desc: stripHtml(decodeEntities(j.content)),
      locName: loc,
      url: j.absolute_url || "",
    });
  }
}
for (const respItem of $("Fetch Careerjet Jobs").all()) {
  const resp = respItem.json || {};
  const jobs = Array.isArray(resp.jobs) ? resp.jobs : [];
  for (const j of jobs) {
    tryAccept({
      title: j.title || "",
      company: j.company || "Unknown",
      desc: stripHtml(decodeEntities(j.description)),
      locName: j.locations || "",
      url: j.url || "",
    });
  }
}
const mapApifyJob = (respItem) => {
  const j = respItem.json || {};
  const locObj = (j.location && typeof j.location === "object") ? j.location : {};
  const locName = [locObj.raw, locObj.locality, locObj.country]
    .filter((v) => v && String(v).trim())
    .join(", ") || (typeof j.location === "string" ? j.location : "");
  const emails = Array.isArray(j.emails) ? j.emails.filter((e) => e && String(e).includes("@")) : [];
  tryAccept({
    title: j.title || j.jobTitle || "",
    company: j.company_name || j.company || "Unknown",
    desc: stripHtml(decodeEntities(j.description || j.summary || "")),
    locName: locName,
    url: j.official_url || j.platform_url || j.url || "",
    email: emails.length ? String(emails[0]).trim() : "",
  });
};
for (const respItem of $("Fetch Bayt Jobs").all()) { mapApifyJob(respItem); }
for (const respItem of $("Fetch Indeed Jobs").all()) { mapApifyJob(respItem); }
return out;

const bases = $('Filter & Map').all();
const cleanedItems = $('Clean Description').all();
const NON_ANSWER_PATTERNS = [
  /no information found/i,
  /please provide (?:the )?(?:full |more )?(?:text|information|details|content)/i,
  /no (?:relevant )?(?:job )?(?:information|content|details|text) (?:was )?(?:found|provided|available)/i,
  /unable to (?:extract|find|process)/i,
  /i (?:cannot|can't|could not|couldn't) (?:extract|find|process|help)/i,
  /there is no (?:text|information|content|job)/i,
  /the (?:provided )?text (?:is empty|does not contain|contains no)/i,
  /^n\/?a$/i,
  /^none$/i,
];
const isNonAnswer = (s) => {
  if (!s) { return true; }
  if (s.length < 25) { return true; }
  return NON_ANSWER_PATTERNS.some((re) => re.test(s));
};
const out = [];
for (let i = 0; i < bases.length; i++) {
  const base = bases[i].json || {};
  const original = (base.job_description || "").trim();
  const cleanedJson = (cleanedItems[i] && cleanedItems[i].json) ? cleanedItems[i].json : {};
  const cleaned = (cleanedJson.text || "").trim();
  const finalDescription = isNonAnswer(cleaned) ? (original || cleaned) : cleaned;
  out.push({ json: { ...base, job_description: finalDescription } });
}
return out;
